package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of integers.
type Matrix *matrix

type matrix struct {
	rows [][]int
}

// New parses s as a matrix of integers. The string is split into rows on
// newlines; each row is a run of whitespace-separated integers. It returns an
// error if any row is empty, any token is not an integer, or the rows have
// differing lengths.
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	rows := make([][]int, len(lines))
	width := -1
	for i, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: row contains no values")
		}
		if width == -1 {
			width = len(fields)
		} else if len(fields) != width {
			return nil, errors.New("matrix: uneven rows")
		}
		row := make([]int, len(fields))
		for j, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[j] = v
		}
		rows[i] = row
	}
	return &matrix{rows: rows}, nil
}

// Cols returns the columns of the matrix, each as a copy of its values,
// without affecting the matrix.
func (m Matrix) Cols() [][]int {
	if len(m.rows) == 0 {
		return [][]int{}
	}
	width := len(m.rows[0])
	cols := make([][]int, width)
	for c := range cols {
		cols[c] = make([]int, len(m.rows))
	}
	for r, row := range m.rows {
		for c, v := range row {
			cols[c][r] = v
		}
	}
	return cols
}

// Rows returns the rows of the matrix as independent copies of their values,
// without affecting the matrix.
func (m Matrix) Rows() [][]int {
	rows := make([][]int, len(m.rows))
	for i, row := range m.rows {
		rows[i] = make([]int, len(row))
		copy(rows[i], row)
	}
	return rows
}

// Set sets the element at row, col to val. It reports whether the position is
// within the matrix.
func (m Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m.rows) || col < 0 || col >= len(m.rows[row]) {
		return false
	}
	m.rows[row][col] = val
	return true
}

